/**
 * Stacked-PR guards must read the repo's REAL trunk, not a guessed one.
 *
 * Both hooks under test used to carry a literal branch list: resolveBase tried
 * ['main', 'master', 'develop'] in that order, and the delete-branch guard
 * printed `git rebase origin/main` plus `gh pr edit <N> --base main` into its
 * advice. In a repo whose trunk is `develop` while `origin/main` still exists
 * as a release branch, both answer "main", which is the wrong branch to
 * measure containment against and the wrong branch to retarget a stacked PR
 * onto.
 *
 * `git symbolic-ref refs/remotes/origin/HEAD` is what actually knows. These
 * tests build REAL throwaway repos (same approach as the #3569 suite next
 * door) with origin/main AND origin/develop present and origin/HEAD pointing
 * at develop, so a hook that guesses cannot accidentally pass.
 *
 * The advice assertions drive the hook end to end through a stub `gh` on PATH,
 * so they fail on the printed string a reader actually sees, not on an
 * internal helper.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync, chmodSync, existsSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { resolveBase } from '../../../pretool/bash/worktree-merge-verifier.js';
import { deleteBranchStackedPRGuard } from '../../../pretool/bash/delete-branch-stacked-pr-guard.js';
import { resolveTrunkBranch } from '../../../lib/git-trunk.js';
import { NOOP_CTX } from '../../../lib/context.js';

let devTrunk: string; // origin/HEAD points at origin/develop, origin/main also exists
let noSymref: string; // origin/main exists, origin/HEAD unset
let empty: string; // no commits, no refs
let binDir: string; // holds the stub `gh`
let originalPath: string | undefined;

function run(args: string[], cwd: string): string {
  return execFileSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
}

function initRepo(prefix: string): string {
  const dir = mkdtempSync(join(tmpdir(), prefix));
  run(['init', '-q', '-b', 'main', '.'], dir);
  run(['config', 'user.email', 't@t.t'], dir);
  run(['config', 'user.name', 't'], dir);
  run(['config', 'commit.gpgsign', 'false'], dir);
  writeFileSync(join(dir, 'f.txt'), 'base\n');
  run(['add', '.'], dir);
  run(['commit', '-qm', 'base'], dir);
  return dir;
}

beforeAll(() => {
  // Trunk is develop; main survives as an older release branch, which is
  // exactly the shape the hardcoded candidate list gets wrong.
  devTrunk = initRepo('ork-trunk-dev-');
  run(['update-ref', 'refs/remotes/origin/main', 'HEAD'], devTrunk);
  run(['checkout', '-qb', 'develop'], devTrunk);
  writeFileSync(join(devTrunk, 'g.txt'), 'dev\n');
  run(['add', '.'], devTrunk);
  run(['commit', '-qm', 'dev work'], devTrunk);
  run(['update-ref', 'refs/remotes/origin/develop', 'develop'], devTrunk);
  run(['symbolic-ref', 'refs/remotes/origin/HEAD', 'refs/remotes/origin/develop'], devTrunk);

  noSymref = initRepo('ork-trunk-nosymref-');
  run(['update-ref', 'refs/remotes/origin/main', 'HEAD'], noSymref);

  empty = mkdtempSync(join(tmpdir(), 'ork-trunk-empty-'));
  run(['init', '-q', '-b', 'main', '.'], empty);

  // Stub gh: `gh pr view ...` names the branch about to be deleted,
  // `gh pr list ...` reports one open PR stacked on it.
  // The head branch it reports is settable, so the injection suite below can
  // hand the guard a hostile branch name over the same path.
  binDir = mkdtempSync(join(tmpdir(), 'ork-trunk-bin-'));
  const gh = join(binDir, 'gh');
  writeFileSync(
    gh,
    [
      '#!/bin/sh',
      'case "$2" in',
      '  view) printf \'%s\\n\' "${ORK_TEST_HEAD_BRANCH:-feat/layer-1}" ;;',
      '  list) echo \'[{"number":42,"title":"feat: layer 2"}]\' ;;',
      '  *) exit 1 ;;',
      'esac',
      '',
    ].join('\n'),
  );
  chmodSync(gh, 0o755);
  originalPath = process.env.PATH;
  process.env.PATH = `${binDir}:${process.env.PATH ?? ''}`;
});

afterAll(() => {
  if (originalPath === undefined) delete process.env.PATH;
  else process.env.PATH = originalPath;
  for (const d of [devTrunk, noSymref, empty, binDir]) {
    if (d) rmSync(d, { recursive: true, force: true });
  }
});

describe('resolveTrunkBranch reads origin/HEAD', () => {
  it('returns the branch origin/HEAD points at, not the first familiar name', () => {
    expect(resolveTrunkBranch(devTrunk)).toBe('develop');
  });

  it('returns null when origin/HEAD is unset, so callers can say so', () => {
    expect(resolveTrunkBranch(noSymref)).toBeNull();
  });
});

describe('worktree-merge-verifier resolveBase follows the real trunk', () => {
  it('measures against origin/develop when that is the trunk, though origin/main exists', () => {
    expect(resolveBase(devTrunk)).toBe('origin/develop');
  });

  it('still falls back to origin/main when origin/HEAD is unset', () => {
    expect(resolveBase(noSymref)).toBe('origin/main');
  });

  it('still returns null when nothing resolves, rather than guessing', () => {
    expect(resolveBase(empty)).toBeNull();
  });
});

describe('delete-branch-stacked-pr-guard advises the real trunk', () => {
  function advice(projectDir: string): string {
    const input = {
      tool_name: 'Bash',
      session_id: 's',
      tool_input: { command: 'gh pr merge 41 --squash --delete-branch' },
    } as never;
    const r = deleteBranchStackedPRGuard(input, { ...NOOP_CTX, projectDir });
    return r.hookSpecificOutput?.additionalContext ?? '';
  }

  it('names the dependent PR it found', () => {
    expect(advice(devTrunk)).toContain('#42');
  });

  it('retargets to the repo trunk, never to a hardcoded main', () => {
    const text = advice(devTrunk);
    expect(text).toContain('--base develop');
    expect(text).not.toContain('--base main');
  });

  it('gives the --onto form, because a plain rebase replays the squashed parent', () => {
    const text = advice(devTrunk);
    expect(text).toContain('git rebase --onto origin/develop');
    expect(text).not.toContain('git rebase origin/main');
  });

  it('names the branch and the expected sha in the force-with-lease', () => {
    expect(advice(devTrunk)).toContain('--force-with-lease=');
  });

  it('tells the reader to record the parent tip before the branch disappears', () => {
    expect(advice(devTrunk)).toContain('git rev-parse origin/feat/layer-1');
  });

  it('says origin/HEAD is unset instead of inventing a trunk', () => {
    const text = advice(noSymref);
    expect(text).toContain('git remote set-head origin -a');
    expect(text).not.toContain('--base main');
  });
});

/**
 * A branch name is attacker controlled. `git check-ref-format` rejects spaces,
 * not shell metacharacters, so `evil;touch /tmp/x` is a legal branch name and a
 * fork PR can carry one. This guard reads that name from `gh pr view` and then
 * passes it to a second command; if that command goes through a shell, the
 * name executes on the operator's machine the moment the guard fires.
 *
 * Same class as the RCE reproduced in worktree-merge-verifier on 2026-08-13,
 * which is why that file's header forbids template literals around git calls.
 * Driven end to end through the stub `gh`, asserting BOTH that the guard still
 * reports correctly AND that the side effect never happened.
 */
describe('delete-branch-stacked-pr-guard does not put branch names in a shell', () => {
  let marker: string;
  let evilBranch: string;
  let priorHeadBranch: string | undefined;

  beforeAll(() => {
    marker = join(tmpdir(), `ork-pwned-${randomUUID()}`);
    // Trailing `#` comments out the rest of the interpolated command line, so
    // under a shell the injected `touch` runs with exactly one argument.
    evilBranch = `evil;touch ${marker} #`;
    priorHeadBranch = process.env.ORK_TEST_HEAD_BRANCH;
    process.env.ORK_TEST_HEAD_BRANCH = evilBranch;
  });

  afterAll(() => {
    if (priorHeadBranch === undefined) delete process.env.ORK_TEST_HEAD_BRANCH;
    else process.env.ORK_TEST_HEAD_BRANCH = priorHeadBranch;
    rmSync(marker, { force: true });
  });

  function run(): string {
    const input = {
      tool_name: 'Bash',
      session_id: 's',
      tool_input: { command: 'gh pr merge 41 --squash --delete-branch' },
    } as never;
    const r = deleteBranchStackedPRGuard(input, { ...NOOP_CTX, projectDir: devTrunk });
    return r.hookSpecificOutput?.additionalContext ?? '';
  }

  it('never executes a command embedded in the head branch name', () => {
    run();
    expect(existsSync(marker)).toBe(false);
  });

  it('still reports the dependent PR, treating the name as opaque text', () => {
    const text = run();
    expect(text).toContain('#42');
    expect(text).toContain(evilBranch);
  });
});
